hero = section('top', crumbs('Belkins') + '<div class="comparison-intro"><h1>The Revenue Inbox vs. Belkins.</h1><p class="lead">Get outbound handled through to qualified booking, with a published $100 fee per qualified booked meeting and a $0-base Basic option. Choose who owns the infrastructure and how quickly you launch.</p><p class="comparison-publisher">Basic vendor bills are additional. Standard and Express include infrastructure we buy and manage.</p><div class="comparison-hero-actions">' + cta('compare-belkins-hero', 'Talk about your campaign') + '<a class="text-link" href="/pricing">See our plans ' + icon() + '</a></div><p class="comparison-meta">By The Revenue Inbox &middot; Sources checked <time datetime="2026-10-22">' + CHECKED + '</time></p></div><nav class="comparison-jumps" aria-label="On this page"><a href="#side-by-side">Side by side</a><a href="#costs">Pricing</a><a href="#fit">Why choose us</a><a href="#proof">Results</a><a href="#sources">Sources</a></nav>', 'comparison-hero')

table = section('side-by-side', intro('See the difference.', 'A comparison of our published offer and Belkins’ official service pages. Checked ' + CHECKED + '.') + '<p class="table-scroll-cue">Swipe the table to compare both agencies.</p><div class="plan-table-scroll" role="region" aria-label="The Revenue Inbox and Belkins service comparison" tabindex="0"><table class="plan-comparison agency-table"><caption>Service scope and billing. Confirm final terms in each proposal.</caption><thead><tr><th scope="col">Decision</th><th scope="col">The Revenue Inbox</th><th scope="col">Belkins</th></tr></thead><tbody>' + ''.join('<tr><th scope="row">' + e(r['dimension']) + '</th><td>' + e(r['ours']) + '</td><td>' + e(r['theirs']) + ' ' + source(r['source']) + '</td></tr>' for r in belkins['rows']) + '</tbody></table></div>')

